    private PlexClient.LibraryPage page()throws Exception{return (PlexClient.LibraryPage)field(home,"catalogPage");}
    private void loaded()throws Exception{await(()->!(Boolean)field(home,"catalogLoading")&&page()!=null,"Catalog did not load");}
    private CatalogFilterSheet sheet()throws Exception{return (CatalogFilterSheet)field(home,"filterSheet");}
    private void open(boolean sort)throws Exception{press((View)field(home,sort?"catalogSort":"catalogFilter"));await(()->sheet()!=null&&field(sheet(),"options")!=null&&!((Boolean)field(sheet(),"loading")),"Filter metadata missing");}
